for (const task of idleTasks) {
  ChromeUtils.idleDispatch(async () => {
    if (!Services.startup.shuttingDown) {
      const startTime = ChromeUtils.now();
      try {
        await task();
      } catch (ex) {
        console.error(ex);
      } finally {
        ChromeUtils.addProfilerMarker("startupLateIdleTask", startTime);
      }
    }
  });
